parameters.jsCode:
// Decide whether a new Amazon search is needed.
// If the screener (or an earlier deep dive) saved this keyword + marketplace in the last 24 hours, reuse that run:
// it saves a search, and the deep dive then describes exactly the same page 1 the screener scored.
const REUSE_HOURS = 24;
const form = $('Deep Dive form').first().json;
const keyword = String(form.Keyword || '').toLowerCase()
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
if (!keyword) throw new Error('No keyword entered. Type a product keyword, e.g. "resistance bands".');
const marketplace = form.Marketplace || 'amazon.com';

// "2026-10-16 13:21:47 UTC" -> milliseconds
const toMs = t => Date.parse(String(t).replace(' UTC', 'Z').replace(' ', 'T'));
const runs = {};
for (const r of $('Read History').all().map(i => i.json)) {
  if (!r.run_id || r.keyword !== keyword || r.marketplace !== marketplace) continue;
  runs[r.run_id] = r.checked_at;
}
const latest = Object.entries(runs).sort((a, b) => toMs(b[1]) - toMs(a[1]))[0];
const ageHours = latest ? (Date.now() - toMs(latest[1])) / 3600000 : null;
const reuse = latest !== undefined && Number.isFinite(ageHours) && ageHours >= 0 && ageHours <= REUSE_HOURS;

return [{
  json: {
    keyword,
    marketplace,
    reuse,
    reuse_run_id: reuse ? latest[0] : null,
    reuse_checked_at: reuse ? latest[1] : null,
    age_hours: ageHours === null ? null : Math.round(ageHours * 10) / 10,
  },
}];

// Bundle what the core needs: either the fresh search or the saved run, plus the history for the stability check.
const src = $('Decide Source').first().json;
let fresh = null;
try {
  if ($('Search Amazon (SerpApi)').isExecuted) fresh = $('Search Amazon (SerpApi)').first().json;
} catch (e) {
  fresh = null; // the search node did not run on this path
}
const history = $('Read History').all().map(i => i.json).filter(r => r.run_id);
const search = { order: 1, keyword: src.keyword, marketplace: src.marketplace };
if (fresh) search.response = fresh;
else search.listings = history.filter(r => r.run_id === src.reuse_run_id);

return [{
  json: {
    tool: 'i2',
    batch_id: $now.toFormat('yyyy-MM-dd HH:mm:ss') + ' PKT',
    searches: [search],
    history,
    dropped: [],
  },
}];

// Choose up to 4 products to look up: the 3 biggest sellers + the best-selling newcomer (if there is one).
// Picked per product FAMILY (variations grouped), so two colours of one product never take two slots.
// Fixed tie-break: sales, then reviews, then page position, so the same data always gives the same picks.
const core = $('Toolkit Core').first().json;
const d = (core.details || [])[0];
if (!d) throw new Error('The core returned no analysis for this keyword.');
const order = (a, b) => (b.units - a.units) || (b.reviews - a.reviews) || (a.position - b.position);
const fams = [...(d.families || [])].sort(order);
const top = fams.slice(0, 3);
// A newcomer means a low-review product from a brand that has NO established (1000+ review) product on the page.
// A big brand's new listing is not a newcomer, so it is skipped (same rule the score uses).
const bkey = b => String(b || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const established = new Set(fams.filter(f => f.reviews >= 1000 && bkey(f.brand)).map(f => bkey(f.brand)));
const low = fams.filter(f => f.reviews < 1000 && f.units > 0 && !top.includes(f) && !established.has(bkey(f.brand))).sort(order)[0];
const picks = [
  ...top.map((f, i) => ({ role: `top seller #${i + 1}`, f })),
  ...(low ? [{ role: 'best newcomer', f: low }] : []),
];
return picks.map(p => ({
  json: {
    role: p.role,
    asin: p.f.best_asin,
    family_id: p.f.family_id,
    family_size: p.f.asins.length,
    brand_guess: p.f.brand ?? '',
    title: p.f.title,
    price: p.f.price,
    rating: p.f.rating,
    reviews: p.f.reviews,
    units_family: p.f.units,
    keyword: d.keyword,
    marketplace: d.marketplace,
    run_id: d.run_id,
  },
}));

// Turn each product-page lookup into one row of facts. Anything the page does not show is "not found", never 0.
// Lookups line up with Pick Products by position; a failed lookup keeps the pick and says why.
const picks = $('Pick Products').all().map(i => i.json);
const pages = $('Look Up Product (SerpApi)').all().map(i => i.json);
const NF = 'not found';

// Find the first value stored under `key` anywhere inside an object (offer layouts differ between products)
function findKey(obj, key, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 6) return undefined;
  if (key in obj) return obj[key];
  for (const v of Object.values(obj)) {
    const hit = findKey(v, key, depth + 1);
    if (hit !== undefined) return hit;
  }
  return undefined;
}
const text = v => (v === undefined || v === null || v === '' ? null : typeof v === 'object' ? (v.text ?? v.content ?? null) : String(v));
function errorText(res) {
  const e = res?.error;
  if (!e) return null;
  let msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  const m = String(msg).match(/\\?"error\\?"\s*:\s*\\?"(.+?)\\?"/);
  return String(m ? m[1] : msg).replace(/\s+/g, ' ').trim().slice(0, 200);
}

return picks.map((p, idx) => {
  const page = pages[idx] || {};
  const base = {
    row_id: `${p.run_id}|${p.asin}`, run_id: p.run_id, keyword: p.keyword, marketplace: p.marketplace,
    role: p.role, asin: p.asin, family_id: p.family_id, family_listings_on_page: p.family_size,
    title: p.title, brand_guess: p.brand_guess, price: p.price, rating: p.rating, reviews: p.reviews,
    units_family_on_page: p.units_family,
  };
  const err = errorText(page);
  const pr = page.product_results;
  if (err || !pr) {
    return { json: { ...base, lookup_status: 'failed', lookup_note: err || 'no product data returned', real_brand: NF, brand_guess_correct: 'unknown', sold_by: NF, ships_from: NF, fulfilled_by_amazon: NF, bsr_category: NF, bsr_all: NF, variations: NF, bought_last_month_page: NF, review_summary: NF, one_two_star_pct: NF, themes: [] } };
  }
  const pd = page.product_details || {};
  const spec = page.item_specifications || {};
  const realBrand = text(pd.brand_name) || text(spec.brand)
    || (pr.brand ? String(pr.brand).replace(/^Brand:\s*/i, '').replace(/^Visit the (.+) Store$/i, '$1').trim() : null);
  const soldBy = text(findKey(page.purchase_options, 'sold_by')) || text(findKey(page.product_results, 'sold_by'));
  const shipsFrom = text(findKey(page.purchase_options, 'ships_from')) || text(findKey(page.product_results, 'ships_from'));
  const bsr = (pd.best_sellers_rank || []).map(b => String(b.text || '').replace(/\s*\(See Top.*?\)\s*/i, '').trim()).filter(Boolean);
  const variants = (pr.variants || []).map(g => `${g.title}: ${(g.items || []).length}`);
  const insights = page.reviews_information?.summary?.insights || [];
  const themes = insights.map(t => ({
    theme: String(t.title || '').trim(),
    sentiment: t.sentiment || '',
    positive: t.mentions?.positive ?? null,
    negative: t.mentions?.negative ?? null,
    total: t.mentions?.total ?? null,
    summary: String(t.summary || '').trim(), // Amazon's own one-line summary of what customers say about this theme
  })).filter(t => t.theme && t.total !== null);
  // Star breakdown (% of ratings per star), when the page shows it
  const stars = page.reviews_information?.summary?.customer_reviews;
  const lowStarPct = stars && typeof stars === 'object' && ('1 star' in stars || '2 star' in stars)
    ? (Number(stars['1 star'] || 0) + Number(stars['2 star'] || 0)) : null;
  const brandKey = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  return {
    json: {
      ...base,
      lookup_status: 'ok',
      lookup_note: themes.length ? '' : 'no review summary on this product page',
      real_brand: realBrand || NF,
      brand_guess_correct: realBrand && p.brand_guess ? (brandKey(realBrand).startsWith(brandKey(p.brand_guess)) || brandKey(p.brand_guess).startsWith(brandKey(realBrand)) ? 'yes' : 'no') : 'unknown',
      sold_by: soldBy || NF,
      ships_from: shipsFrom || NF,
      fulfilled_by_amazon: shipsFrom ? (/amazon/i.test(shipsFrom) ? 'yes' : 'no') : NF,
      bsr_category: bsr.length ? bsr[bsr.length - 1] : NF,
      bsr_all: bsr.length ? bsr.join(' | ') : NF,
      variations: variants.length ? variants.join(', ') : 'none listed',
      bought_last_month_page: pr.bought_last_month || NF,
      review_summary: page.reviews_information?.summary?.text || NF,
      one_two_star_pct: lowStarPct === null ? NF : lowStarPct,
      themes,
    },
  };
});

// Build the evidence table the AI is allowed to use. Each theme gets an ID (T1, T2, ...).
// Counts are Amazon's own review-summary mention counts. Different products have very different review totals,
// so each theme is judged by the SHARE of its mentions that are negative, and by how many products raise it,
// never by raw counts.
const products = $('Extract Products').all().map(i => i.json);
const norm = s => s.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const label = p => (p.real_brand && p.real_brand !== 'not found' ? p.real_brand : p.brand_guess || p.asin);

const byTheme = {};
for (const p of products) {
  for (const t of p.themes || []) {
    const key = norm(t.theme);
    const e = (byTheme[key] ??= { theme: t.theme, products: [] });
    e.products.push({ product: label(p), role: p.role, positive: t.positive ?? 0, negative: t.negative ?? 0, total: t.total ?? 0, summary: t.summary || '' });
  }
}
const inspected = products.filter(p => p.lookup_status === 'ok').length;
const withThemes = products.filter(p => (p.themes || []).length).length;
const themes = Object.values(byTheme).map(e => {
  const pos = e.products.reduce((s, x) => s + x.positive, 0);
  const neg = e.products.reduce((s, x) => s + x.negative, 0);
  const tot = e.products.reduce((s, x) => s + x.total, 0);
  return { ...e, positive: pos, negative: neg, total: tot, negative_pct: tot ? Math.round(neg / tot * 100) : 0, product_count: e.products.length };
})
  // Most widespread first, then most mentioned
  .sort((a, b) => (b.product_count - a.product_count) || (b.total - a.total))
  .map((t, i) => ({ id: `T${i + 1}`, ...t }));

// The AI sees IDs, names and shares. It writes ideas only; code writes every number afterwards.
const table = themes.map(t =>
  `${t.id} | ${t.theme} | raised on ${t.product_count} of ${withThemes} products | ${t.negative_pct}% of its mentions negative`
  + t.products.filter(x => x.summary).map(x => `\n     Amazon's summary for ${x.product}: "${x.summary}"`).join('')
).join('\n');
const core = $('Toolkit Core').first().json.details[0];
const prompt = `You help an Amazon seller decide how a new product could stand out in the "${core.keyword}" market.

Below are review themes from the best-selling products, summarised by Amazon from customer reviews. Each has an ID.
Use ONLY these themes and Amazon's summaries. Do not invent themes, products, brands or facts, and do not add product details\n(materials, parts, causes) that the summaries do not mention.

${table}

Return JSON with:
- "angles": up to 3 ways a new product could stand out. Each angle must fix something customers complain about in the themes listed (a theme with a high negative share). Each has:
    "theme_ids": the IDs it is based on (e.g. ["T2"]),
    "angle": one short sentence describing the product idea,
    "why": one short sentence linking the idea to the complaint, using only what Amazon's summary says.
- "must_match": IDs of themes customers clearly like (low negative share, raised on several products). A new product must at least match these.

Rules:
- Do not write any digits or numbers in "angle" or "why". The numbers are added from the data afterwards.
- If no theme has a meaningful share of complaints, return an empty "angles" list.
- Use only IDs from the list above.`;

return [{
  json: {
    themes,
    products_inspected: inspected,
    products_with_themes: withThemes,
    products_total: products.length,
    prompt,
    skip_ai: themes.length === 0,
  },
}];

