{
  "angles": [
    {
      "theme_ids": [
        "T2"
      ],
      "angle": "One short sentence describing the product idea.",
      "why": "One short sentence linking it to the complaint."
    }
  ],
  "must_match": [
    "T1"
  ]
}

parameters.jsCode:
// Check the AI's answer against the evidence table, then write the final text with numbers taken from the data.
// The AI only chooses themes and phrases ideas. Every number shown to the user is written here, by code.
const ev = $('Build Evidence').first().json;
const core = $('Toolkit Core').first().json;
const d = core.details[0];
const s = d.stats;
const products = $('Extract Products').all().map(i => i.json);
const byId = Object.fromEntries(ev.themes.map(t => [t.id, t]));
const warnings = [];
const MIN_COMPLAINT_PCT = 20; // an angle must rest on a theme with at least this share of negative mentions
const MAX_PRAISE_NEG_PCT = 25; // a "must match" theme must be mostly praised
const MATERIALS = /\b(steel|stainless|aluminium|aluminum|metal|iron|titanium|carbon|plastic|silicone|rubber|latex|tpe|pvc|foam|memory foam|cotton|polyester|microfiber|microfibre|bamboo|wood|wooden|leather|nylon|glass|ceramic|copper|brass|reinforced)\b/g;

let ai = null;
let aiStatus;
if (ev.skip_ai) {
  aiStatus = 'skipped: none of the inspected products has a review summary';
} else {
  let raw = null;
  try {
    if ($('Write Angles (AI)').isExecuted) raw = $('Write Angles (AI)').first().json;
  } catch (e) { raw = null; }
  if (!raw) aiStatus = 'failed: the AI step did not run';
  else if (raw.error) aiStatus = `failed: ${String(raw.error.message || raw.error).slice(0, 150)}`;
  else {
    ai = raw.output ?? raw;
    if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = null; } }
    aiStatus = ai && typeof ai === 'object' ? 'ok' : 'failed: the AI answer was not valid JSON';
  }
}

// Evidence line for one theme, from the data only
const evidence = t => `${t.theme}: ${t.negative} of ${t.total} mentions negative (${t.negative_pct}%), raised on ${t.product_count} of ${ev.products_with_themes} products [`
  + t.products.map(x => `${x.product} ${x.negative}/${x.total}`).join(', ') + ']'
  + t.products.filter(x => x.summary).map(x => ` Amazon says (${x.product}): "${x.summary}"`).join('');
// Amazon only shows its review summary on some product pages, so say how much of the evidence exists
const coverage = `Review themes found on ${ev.products_with_themes} of ${ev.products_total} inspected products`
  + (ev.products_with_themes === 1 ? ' (single-product evidence: treat the angles as leads, not conclusions)' : '')
  + (ev.products_with_themes === 0 ? ' (Amazon showed no review summary on these pages)' : '') + '.';

const angles = [];
for (const a of (ai?.angles || []).slice(0, 5)) {
  const ids = (Array.isArray(a.theme_ids) ? a.theme_ids : []).map(String);
  const known = ids.filter(id => byId[id]);
  const unknown = ids.filter(id => !byId[id]);
  if (unknown.length) warnings.push(`AI used unknown theme IDs ${unknown.join(', ')}; ignored`);
  if (!known.length) { warnings.push(`Dropped an angle with no valid theme: "${String(a.angle || '').slice(0, 60)}"`); continue; }
  if (/\d/.test(`${a.angle} ${a.why}`)) { warnings.push(`Dropped an angle that contained numbers (numbers must come from the data): "${String(a.angle).slice(0, 60)}"`); continue; }
  const complaints = known.filter(id => byId[id].negative_pct >= MIN_COMPLAINT_PCT);
  if (!complaints.length) { warnings.push(`Dropped an angle based only on themes customers mostly like (${known.join(', ')})`); continue; }
  // The AI sometimes adds a material or part that Amazon's summaries never mention. Flag it (the idea may still be fine).
  const said = known.map(id => byId[id].products.map(x => x.summary).join(' ') + ' ' + byId[id].theme).join(' ').toLowerCase();
  const added = (`${a.angle} ${a.why}`.toLowerCase().match(MATERIALS) || []).filter(w => !said.includes(w));
  if (added.length) warnings.push(`Angle "${String(a.angle).slice(0, 50)}" mentions ${[...new Set(added)].join(', ')}, which Amazon's summaries do not; treat that detail as the AI's suggestion`);
  if (angles.length >= 3) { warnings.push('AI returned more than 3 angles; kept the first 3'); break; }
  angles.push({ angle: String(a.angle || '').trim(), why: String(a.why || '').trim(), ids: complaints });
}
const mustMatch = [];
for (const id of (ai?.must_match || []).map(String)) {
  const t = byId[id];
  if (!t) { warnings.push(`AI listed unknown must-match ID ${id}; ignored`); continue; }
  if (t.negative_pct > MAX_PRAISE_NEG_PCT) { warnings.push(`Removed ${id} (${t.theme}) from must-match: ${t.negative_pct}% of its mentions are negative`); continue; }
  mustMatch.push(t);
}
if (aiStatus === 'ok' && warnings.length) aiStatus = 'ok, with fixes (see ai_warnings)';

// How much evidence sits under an angle: products raising the theme and how many complaints
const strength = a => {
  const ts = a.ids.map(id => byId[id]);
  const prods = Math.max(...ts.map(t => t.product_count));
  const neg = ts.reduce((n, t) => n + t.negative, 0);
  return `${prods} of ${ev.products_with_themes} products, ${neg} complaints${prods === 1 || neg < 30 ? ', weak evidence' : ''}`;
};
const anglesText = coverage + '\n' + (angles.length
  ? angles.map((a, i) => `${i + 1}. ${a.angle} [${strength(a)}] Why: ${a.why} Evidence: ${a.ids.map(id => evidence(byId[id])).join('; ')}`).join('\n')
  : (aiStatus.startsWith('ok') ? 'No angle: no theme drew a meaningful share of complaints on the inspected products.' : `No angles (${aiStatus}). The evidence table is still saved in themes_table.`));
const productsText = products.map(p => `${p.role}: ${p.real_brand && p.real_brand !== 'not found' ? p.real_brand : p.brand_guess || '?'} (${p.asin}, ${p.lookup_status === 'ok' ? `${p.bsr_category}, sold by ${p.sold_by}, Amazon ships: ${p.fulfilled_by_amazon}` : `lookup failed: ${p.lookup_note}`})`).join(' | ');
const CANNOT_TELL = 'how many shoppers search this keyword | profit, fees or margins | whether demand is rising or falling | how long products have been on sale | review themes come from Amazon\'s summary of each product\'s reviews, not from reading every review';

const row = {
  row_id: `${d.run_id}|deep dive`,
  tool: 'i2',
  checked_at: d.checked_at,
  keyword: d.keyword,
  marketplace: d.marketplace,
  data_source: d.reused ? `reused saved run from ${d.checked_at} (no new search)` : 'new search',
  opportunity_score: s.opportunity_score,
  confidence: d.confidence,
  stability: d.stability,
  price_p25: s.price_p25,
  price_median: s.price_median,
  price_p75: s.price_p75,
  median_reviews: s.median_reviews,
  units_last_month_floor: s.units_last_month_floor,
  revenue_last_month_floor: s.revenue_last_month_floor,
  top3_brands_sales_share_pct: s.top3_brands_sales_share_pct,
  low_review_sales_share_pct: s.low_review_sales_share_pct,
  products_inspected: productsText,
  angles: anglesText,
  must_match: mustMatch.length ? mustMatch.map(evidence).join('; ') : 'none identified',
  themes_table: ev.themes.length ? ev.themes.map(t => `${t.id} ${evidence(t)}`).join('\n') : 'no review summaries found',
  ai_status: aiStatus,
  ai_warnings: warnings.join(' | '),
  score_breakdown: (s.score_breakdown || []).join(' | '),
  confidence_notes: d.confidence_notes,
  cannot_tell: CANNOT_TELL,
  core_version: s.core_version,
  run_id: d.run_id,
};
const cur = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' }[d.marketplace] ?? '';
const lowWhy = d.confidence === 'low' && d.confidence_notes
  ? `\nWhy low: ${String(d.confidence_notes).split(' | ').filter(n => !/^reused/.test(n)).slice(0, 2).join('; ')}` : '';
const summary = `${d.keyword} (${d.marketplace}): ${s.opportunity_score}/100, confidence ${d.confidence}${lowWhy}`
  + `\nPrice band ${cur}${s.price_p25} – ${cur}${s.price_p75}, at least ${s.units_last_month_floor} units sold last month on page 1`
  + `\n\n${coverage}\nAngles:\n${angles.length ? angles.map((a, i) => `${i + 1}. ${a.angle} [${strength(a)}]`).join('\n') : (aiStatus.startsWith('ok') ? 'none: no theme drew a meaningful share of complaints' : `none (${aiStatus})`)}`;
return [{ json: { ...row, summary_text: summary } }];

// One Products-tab row per inspected product; review themes written out as text
return $('Extract Products').all().map(i => {
  const { themes, ...p } = i.json;
  return {
    json: {
      ...p,
      review_themes: (themes || []).map(t => `${t.theme}: ${t.positive} positive / ${t.negative} negative of ${t.total} mentions${t.summary ? ` (Amazon: "${t.summary}")` : ''}`).join(' | ') || 'none',
    },
  };
});

// The Deep Dive row without the form-only summary text
const { summary_text, ...row } = $('Validate & Write').first().json;
return [{ json: row }];

// ---- Result page: shared design (Amazon Toolkit). Presentation only: every value is copied from earlier nodes. ----
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const CURS = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' };
const num = v => (v === '' || v === null || v === undefined || Number.isNaN(Number(v)) ? null : Number(v));
const int = v => (num(v) === null ? '–' : Math.round(num(v)).toLocaleString('en-US'));
const money = (v, cur) => (num(v) === null ? '–' : `${cur}${num(v).toFixed(2)}`);
const big = (v, cur = '') => { const n = num(v); if (n === null) return '–'; if (n >= 1e6) return `${cur}${(n / 1e6).toFixed(2)}M`; if (n >= 1e4) return `${cur}${Math.round(n / 1e3)}K`; return `${cur}${int(n)}`; };
const rating = v => (num(v) === null ? '–' : num(v).toFixed(1));
const spots = t => esc(String(t ?? '').split(' | ').join(' · '));
const split = t => String(t ?? '').split(' | ').map(s => s.trim()).filter(Boolean);
const LEVEL = { high: 'yes', medium: 'mid', low: 'no' };
const pill = (text, kind) => `<span class="pill ${kind || ''}">${esc(text)}</span>`;
const levelPill = t => pill(t, LEVEL[String(t || '').toLowerCase()] || 'muted');
const tiles = list => `<div class="tiles">${list.map(([v, l]) => `<div class="tile"><div class="tv">${v}</div><div class="tl">${esc(l)}</div></div>`).join('')}</div>`;
const section = (title, body) => (body ? `<section><h2>${esc(title)}</h2>${body}</section>` : '');
const table = (head, rows, right = []) => `<div class="tw"><table><thead><tr>${head.map((h, i) => `<th${right.includes(i) ? ' class="r"' : ''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td${right.includes(i) ? ' class="r"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const notesList = list => (list.length ? `<ul class="notes">${list.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : '');
const chips = list => (list.length ? `<div class="chips">${list.map(c => `<span class="chip">${esc(c)}</span>`).join('')}</div>` : '');

function page({ code, tool, colour, tint, title, meta, verdict, body, saved, cannotTell }) {
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(tool)} · ${esc(title)}</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600&family=Source+Serif+4:opsz,wght@8..60,600&display=swap');
*{box-sizing:border-box}
body{margin:0;background:${tint};color:#1f2328;font:14px/1.55 Inter,'Segoe UI',Helvetica,Arial,sans-serif}
.wrap{max-width:760px;margin:0 auto;padding:28px 16px 48px}
.card{background:#fff;border:1px solid #e2ddd5;border-radius:6px;overflow:hidden;box-shadow:0 8px 28px rgba(13,27,42,.08)}
header{background:${colour};color:#fff;padding:26px 28px 22px;border-bottom:5px solid #9C7A3C}
.label{font:12px/1 ui-monospace,Consolas,monospace;letter-spacing:3px;color:#D8CBB8;text-transform:uppercase}
h1{font:600 30px/1.2 'Source Serif 4',Georgia,serif;margin:10px 0 6px}
.meta{color:#D8CBB8;font-size:13px}
.verdict{padding:22px 28px;border-bottom:1px solid #eee7dc;background:#fbfaf7}
.verdict .big{font:600 22px/1.3 'Source Serif 4',Georgia,serif;color:${colour}}
.verdict p{margin:6px 0 0;color:#3d434a}
.content{padding:6px 28px 26px}
section{margin-top:22px}
h2{font:600 12px/1 Inter,sans-serif;letter-spacing:2px;text-transform:uppercase;color:${colour};margin:0 0 10px;padding-bottom:8px;border-bottom:2px solid #9C7A3C;display:inline-block}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:10px;margin-top:4px}
.tile{border:1px solid #e2ddd5;border-top:3px solid ${colour};border-radius:4px;padding:12px 14px;background:#fff}
.tv{font:600 20px/1.2 'Source Serif 4',Georgia,serif;color:#1f2328}
.tl{font-size:12px;color:#5f6670;margin-top:4px}
.tw{overflow-x:auto;border:1px solid #e2ddd5;border-radius:4px}
