.pill.yes{background:#014D4E;color:#fff}.pill.mid{background:#301934;color:#fff}.pill.no{background:#DC143C;color:#fff}.pill.muted{background:#eceae6;color:#5f6670}
.notes{margin:0;padding-left:18px;color:#3d434a}.notes li{margin:4px 0}
.chips{display:flex;flex-wrap:wrap;gap:6px}
