</style></head><body><div class="wrap"><div class="card">
<header><div class="label">Amazon Toolkit · ${esc(code)} ${esc(tool)}</div><h1>${esc(title)}</h1><div class="meta">${meta.map(esc).join(' &nbsp;·&nbsp; ')}</div></header>
${verdict ? `<div class="verdict">${verdict}</div>` : ''}
<div class="content">${body}
${section('Cannot tell from this data', chips(cannotTell || []))}
</div>
<footer>Saved to the sheet: ${esc(saved)}. Every number recomputes from the Listings tab.</footer>
</div></div></body></html>`;
}
// i2 Market Deep Dive: result page
const v = $('Validate & Write').first().json;
const cur = CURS[v.marketplace] || '';
const lines = String(v.angles || '').split('\n').map(s => s.trim()).filter(Boolean);
const coverage = lines.filter(l => !/^\d+\./.test(l)).join(' ');
const angles = lines.filter(l => /^\d+\./.test(l)).map(l => {
  const m = l.match(/^(\d+)\.\s+(.*?)(?:\s+\[([^\]]*)\])?\s+Why:\s+(.*?)\s+Evidence:\s+(.*)$/);
  if (!m) return `<div class="item">${esc(l)}</div>`;
  const ev = m[5].split(' Amazon says')[0];
  return `<div class="item"><b>${esc(m[1])}. ${esc(m[2])}</b>${m[3] ? ` <span class="sub">[${esc(m[3])}]</span>` : ''}<div style="margin-top:4px">${esc(m[4])}</div><div class="sub" style="margin-top:4px">${esc(ev)}</div></div>`;
}).join('');
const must = String(v.must_match || '').split('; ').filter(s => s && s !== 'none identified').map(s => s.split(' Amazon says')[0]);
const prods = split(v.products_inspected).map(p => {
  const m = p.match(/^(.*?):\s+(.*?)\s+\((\w{10}),\s*(.*?),\s*sold by (.*?),\s*Amazon ships: (.*?)\)$/);
  return m ? [esc(m[1]), `<b>${esc(m[2])}</b><div class="sub">${esc(m[3])}</div>`, esc(m[4]), esc(m[5])] : [esc(p), '', '', ''];
});
const conf = split(v.confidence_notes).filter(n => !/^reused/.test(n));
const html = page({
  code: 'i2', tool: 'Market Deep Dive', colour: '#0F3D3E', tint: '#edf4f3',
  title: v.keyword, meta: [v.marketplace, v.data_source, v.core_version],
  verdict: `<div class="big">${esc(v.opportunity_score)}/100 &nbsp;${levelPill(v.confidence)}</div>${conf.length ? `<p>${esc(conf.slice(0, 2).join(' · '))}</p>` : ''}`,
  body: [
    tiles([[`${money(v.price_p25, cur)}–${money(v.price_p75, cur)}`, `price band, median ${money(v.price_median, cur)}`], [`${int(v.units_last_month_floor)}+`, 'bought last month (floor)'], [big(v.revenue_last_month_floor, cur) + '+', 'revenue last month (floor)'], [`${esc(v.top3_brands_sales_share_pct)}%`, 'held by the top 3 brands'], [`${esc(v.low_review_sales_share_pct)}%`, 'of sales to newcomers']]),
    section('Angles to build on', (coverage ? `<p class="sub">${esc(coverage)}</p>` : '') + (angles || `<p>No angles. AI status: ${esc(v.ai_status)}</p>`)),
    section('Must match', must.length ? notesList(must) : ''),
    section('Products inspected', prods.length ? table(['Role', 'Brand', 'Best-seller rank', 'Sold by'], prods) : ''),
    section('Checks on the AI', v.ai_warnings ? notesList(split(v.ai_warnings)) : ''),
  ].join(''),
  saved: 'Deep Dive, Products, Listings',
  cannotTell: split(v.cannot_tell),
});
return [{ json: { html } }];
